def count_unique_emojis(text):
    # Use regex to match emoji characters
    emoji_pattern = re.compile(
        "["
        "\U0001F600-\U0001F64F"  # emoticons
        "\U0001F300-\U0001F5FF"  # symbols & pictographs
        "\U0001F680-\U0001F6FF"  # transport & map symbols
        "\U0001F700-\U0001F77F"  # alchemical symbols
        "\U0001F780-\U0001F7FF"  # Geometric Shapes
        "\U0001F800-\U0001F8FF"  # Supplemental Arrows-C
        "\U0001F900-\U0001F9FF"  # Supplemental Symbols and Pictographs
        "\U0001FA00-\U0001FA6F"  # Chess Symbols
        "\U0001FA70-\U0001FAFF"  # Symbols and Pictographs Extended-A
        "\U00002702-\U000027B0"  # Dingbats
        "\U000024C2-\U0001F251" 
        "]+"
    )

    emojis = emoji_pattern.findall(text)
    unique_emojis = set(emojis)

    print(f"Total emojis: {len(emojis)}")
    print(f"Unique emojis: {len(unique_emojis)}")

    emoji_count = {}
    for emoji in emojis:
        if emoji in emoji_count:
            emoji_count[emoji] += 1
        else:
            emoji_count[emoji] = 1

    print("\nEmoji counts:")
    for emoji, count in sorted(emoji_count.items(), key=lambda x: x[1], reverse=True):
        code_point = ord(emoji)
        print(f"{emoji}: {count} times (U+{code_point:X})")

    return emojis, unique_emojis, emoji_count

def map_to_brainfuck(emojis, emoji_count):
    # Try to map the 8 most common emojis to Brainfuck commands
    bf_commands = ['>', '<', '+', '-', '.', ',', '[', ']']

